285:       const adjustedWindowSize = {...driverWindowSize};
286:       const {realDisplaySize} = await this.driver.executeScript('mobile:deviceInfo', []);
287:       // realDisplaySize value fits portrait mode for phones, but landscape mode for tablets
288:       const [width, height] = realDisplaySize.split('x').map((param) => parseInt(param, 10));
