473:   /**
474:    * Parse the Android contexts webview data
475:    *
476:    * Returns
477:    * {
478:    *   id: string;             // NATIVE_APP or the webview name
479:    *   title?: string;         // the name of the page
480:    *   url?: string;           // the url
481:    *   bundleId?: string;      // for iOS
482:    *   packageName?: string;   // for Android
483:    *   handle?: string;        // the id of the active page in the webview of Android
484:    * }[];
485:    */
486:   parseAndroidContexts(contexts) {
487:     const parsedWebviews = [];
488: 
489:     // Walk over every context and add all webviews into the parsedWebviews array
490:     contexts
491:       // Filter out all contexts that have a webviewName
492:       .filter((webview) => _.has(webview, 'webviewName'))
493:       // Now construct a new array with data
494:       .map(({info, pages, webviewName}) => {
495:         // The context result can have:
496:         // - no pages => this might be Chrome running in the background
497:         // - pages => this can be:
498:         //   - Chrome with one or multiple tabs open
499:         //   - A webview with one or multiple webviews
500:         if (!pages) {
501:           return;
502:         }
503: 
504:         pages
505:           .filter((page) => {
506:             // The description is a string and:
507:             // 1. can contain a JSON string for webviews which can contain
508:             //    an `attached`-value telling if the webview is active
509:             // 2. can be an empty string, this is most of the times for tabs
510:             //    in Chrome
511:             const description = _.has(page, 'description') ? page.description : '';
512:             let descriptionJSON = {attached: false};
513:             try {
514:               descriptionJSON = JSON.parse(page.description);
515:             } catch {}
516: 
517:             // You can have multiple `type` of pages, like service workers
518:             // We need to have pages with or 1. an attached view or 2. with an empty description
519:             return page.type === 'page' && (description === '' || descriptionJSON.attached);
520:           })
521:           .map((page) => {
522:             parsedWebviews.push({
523:               id: webviewName,
524:               ...(page && _.has(page, 'title') ? {title: page.title} : {}),
525:               ...(page && _.has(page, 'url') ? {url: page.url} : {}),
526:               ...(page && _.has(info, 'Android-Package')
527:                 ? {packageName: info['Android-Package']}
528:                 : {}),
529:               ...(page && _.has(page, 'id') ? {handle: page.id} : {}),
530:             });
531:           });
532: 
533:         return parsedWebviews;
534:       });
535: 
536:     return [
537:       // The Android contexts dont have the `NATIVE_APP` context so add it here
538:       {id: NATIVE_APP},
539:       // Add the parsedWebviews, but make sure to filter out all undefined webviews
540:       ...parsedWebviews.filter(Boolean),
541:     ];
