60: // GET returning { status, body } (does NOT throw on 4xx — 404 is a real answer).
61: function httpGet(url, redirects = 1) {
62:   return new Promise((resolve, reject) => {
63:     const req = https.get(url, { headers: { 'User-Agent': 'pc-lib-analysis/1.0' } }, (res) => {
64:       const { statusCode, headers } = res;
65:       if (statusCode >= 300 && statusCode < 400 && headers.location && redirects > 0) {
66:         res.resume();
67:         return resolve(httpGet(new URL(headers.location, url).toString(), redirects - 1));
68:       }
69:       let body = '';
70:       res.setEncoding('utf8');
71:       res.on('data', (c) => (body += c));
72:       res.on('end', () => resolve({ status: statusCode, body }));
73:     });
