92: // 'list' strategy: fetch the cmd-pkgs README once, harvest every prebuilt package
93: // name from its install commands (`sh -s -- <name> <version>`), cache as a Set.
94: async function adaptedList(cfg, refresh = false) {
95:   const c = loadCache();
96:   const cacheKey = `_list:${cfg.listKey}`;
97:   const entry = c[cacheKey];
98:   if (!refresh && entry && Date.now() - (entry.ts || 0) < CACHE_TTL_MS) return new Set(entry.names || []);
99:   let r;
100:   try { r = await httpGet(cfg.url); } catch { return entry ? new Set(entry.names) : null; }
101:   if (!r || r.status < 200 || r.status >= 300) return entry ? new Set(entry.names) : null;
102:   const names = new Set();
103:   const re = /sh\s+-s\s+--\s+([a-z0-9._+-]+)/gi;
104:   let m;
105:   while ((m = re.exec(r.body))) names.add(m[1].toLowerCase());
106:   c[cacheKey] = { names: [...names], ts: Date.now() };
107:   saveCache();
108:   return names;
109: }
